select private.seed_lang_examples('vi', 'vi', $doc${"official":{"display_name":"PinWith Chính thức","bio":"Những danh sách địa điểm do đội ngũ PinWith tuyển chọn."},"samples":[{"display_name":"Người dùng mẫu 1","bio":"Tài khoản mẫu do PinWith tạo để minh họa cách bạn bè cùng nhau lên kế hoạch cho một chuyến đi."},{"display_name":"Người dùng mẫu 2","bio":"Tài khoản mẫu do PinWith tạo để minh họa cách bạn bè cùng nhau lên kế hoạch cho một chuyến đi."},{"display_name":"Người dùng mẫu 3","bio":"Tài khoản mẫu do PinWith tạo để minh họa cách bạn bè cùng nhau lên kế hoạch cho một chuyến đi."}],"lists":[{"role":"plain","owner":"official","slug":"ha-noi-pho-co-di-bo","kind":"course","title":"Một buổi dạo phố cổ Hà Nội","desc":"Lộ trình đi bộ nửa ngày quanh phố cổ: từ cửa ô cổ còn sót lại, qua phố đi bộ hồ Gươm, ngồi bia hơi Tạ Hiện rồi kết thúc ở phố đường tàu.","themes":["HàNội","phốcổ","đibộ","cuốituần"],"sections":[{"name":"Lõi phố cổ","by":"official","items":[{"place_id":"ChIJp0o4Er6rNTERjlTif_IXU1k","title":"Phố cổ Hà Nội","memo":"Mỗi con phố \"Hàng\" từng gắn với một nghề riêng; đi sáng sớm để thấy cảnh buôn bán và ăn sáng vỉa hè đúng chất Hà Nội.","tags":["phốcổ","buổisáng"],"lat":21.034059,"lng":105.850637},{"place_id":"ChIJb77ZudmrNTER8NtTmG8Fojs","title":"Ô Quan Chưởng","memo":"Cửa ô duy nhất của Thăng Long xưa còn giữ được đến nay; ghé buổi chiều khi nắng xiên vào cổng gạch để chụp ảnh đẹp nhất.","tags":["ditích","chụpảnh"],"lat":21.037311,"lng":105.852115},{"place_id":"ChIJ87NZ0GqrNTERFlxiMWBA2pQ","title":"Phố đi bộ Hồ Gươm","memo":"Chỉ cấm xe vào tối thứ Sáu đến hết Chủ nhật; có biểu diễn đường phố, trò chơi dân gian và rất đông người, nhớ giữ đồ cẩn thận.","tags":["cuốituần","buổitối"],"lat":21.031596,"lng":105.853072}]},{"name":"Tối ở phố cổ","by":"official","items":[{"place_id":"ChIJd64Vx8CrNTERulxZIacQ3Bg","title":"Phố bia Tạ Hiện","memo":"Ngồi ghế nhựa uống bia hơi nhìn dòng người qua lại là trải nghiệm không thể thiếu; nên hỏi giá đồ nhắm trước khi gọi.","tags":["biahơi","vềđêm"],"lat":21.034621,"lng":105.85234}]},{"name":"Phố đường tàu","by":"official","items":[{"place_id":"ChIJ81hOVwCrNTER5Wom14N93Ug","title":"Phố đường tàu Trần Phú","memo":"Đoạn đường tàu len giữa những dãy nhà sát nhau; quy định tham quan thay đổi theo thời điểm, nên tuân thủ hướng dẫn và luôn đứng cách xa đường ray.","tags":["đườngtàu","chụpảnh"],"lat":21.029592,"lng":105.843335},{"place_id":"ChIJk3T9H52rNTERWEi_m8jbA_4","title":"Phố đường tàu Khâm Thiên","memo":"Đoạn phía nam thường ít đông hơn khu Trần Phú; hỏi các quán cà phê ven đường về giờ tàu chạy để không phải chờ lâu.","tags":["đườngtàu","ítđông"],"lat":21.017818,"lng":105.840853},{"place_id":"ChIJDW4dgOerNTERG2YjfEx85I8","title":"Cafe 61 phố đường tàu","memo":"Quán nhỏ ngay sát đường ray, hợp để ngồi nghỉ chân với ly cà phê trứng hoặc cà phê muối sau khi đi bộ cả buổi.","tags":["càphê","nghỉchân"],"lat":21.017628,"lng":105.840885}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-da-nang-hoi-an","kind":"course","title":"[Vlog] Đà Nẵng – Hội An 3 ngày: núi, hang động và phố đèn lồng","desc":"Những điểm mình đã quay trong vlog Đà Nẵng – Hội An, kèm góc máy, khung giờ ánh sáng đẹp và mẹo né đông người.","themes":["vlog","ĐàNẵng","HộiAn","chụpảnh","miềnTrung"],"sections":[{"name":"Ngày 1 – Ngũ Hành Sơn","by":"official","items":[{"place_id":"ChIJP17efe8RQjER-uxBu6RK0s4","title":"Ngũ Hành Sơn","memo":"Trong vlog đoạn phút 2:10 mình leo Thủy Sơn lúc 7 giờ sáng: trời mát, chưa có đoàn khách. Đi giày đế bám vì bậc đá khá trơn.","tags":["leonúi","buổisáng"],"lat":16.00291,"lng":108.263829},{"place_id":"ChIJ8be7KQARQjER5Lnd2LHaDAs","title":"Động Huyền Không","memo":"Cảnh \"tia nắng rọi xuống hang\" đẹp nhất vào khoảng gần trưa khi trời nắng; đặt máy thấp, phơi sáng theo vùng sáng để không cháy trời.","tags":["hangđộng","gócmáy"],"lat":16.004281,"lng":108.262067},{"place_id":"ChIJ3a8dOgARQjERJ1pdjlegJds","title":"Làng đá Non Nước","memo":"Ngay chân núi, quay cận cảnh các nghệ nhân đục đá rất có chất; xin phép trước khi quay người làm việc nhé.","tags":["lànhnghề","broll"],"lat":16.002126,"lng":108.263317}]},{"name":"Ngày 2 – Bà Nà","by":"official","items":[{"place_id":"ChIJyWFmArX3QTERon6tUT6re4Q","title":"Bà Nà Hills","memo":"Lên chuyến cáp treo sớm để quay Cầu Vàng khi còn vắng; trên núi lạnh và hay có sương mù, nhớ mang áo khoác và khăn lau ống kính.","tags":["cầuVàng","đisớm"],"lat":15.995136,"lng":107.996139}]},{"name":"Ngày 3 – Hội An","by":"official","items":[{"place_id":"ChIJWewCLXwOQjERRkh9adZkWHY","title":"Chùa Cầu","memo":"Biểu tượng của Hội An; ra lúc bình minh để có khung hình không người, còn buổi tối thì quay timelapse đèn lồng từ bờ sông đối diện.","tags":["phốcổ","bìnhminh"],"lat":15.877087,"lng":108.32607},{"place_id":"ChIJCd1dxooPQjERnwGkP80bMN0","title":"Làng mộc Kim Bồng","memo":"Đi đò từ phố cổ qua sông chỉ vài phút; đoạn 6:45 trong vlog là cảnh thuyền cập bến lúc hoàng hôn, rất đáng thử.","tags":["điđò","hoànghôn"],"lat":15.865156,"lng":108.32423},{"place_id":"ChIJew92MdgPQjER_xtGbehPkcY","title":"Đảo Cẩm Kim","memo":"Thuê xe đạp đi vòng quanh đảo giữa ruộng rau và rặng dừa; quay drone nhớ kiểm tra quy định bay tại khu vực trước.","tags":["xeđạp","đồngquê"],"lat":15.862381,"lng":108.32347}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"seoul-busan-5-ngay-3-dua-ban","kind":"collection","title":"Seoul + Busan 5 ngày cùng hội bạn thân","desc":"Ba đứa mỗi đứa ghim một nhóm địa điểm muốn đi rồi bàn trong phần bình luận. Lịch trình chốt cuối cùng nằm trong bình luận ở Cung Gyeongbok!","themes":["HànQuốc","Seoul","Busan","đinhóm","lịchtrình"],"sections":[{"name":"Seoul cổ kính","by":"ex1","items":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","title":"Cung Gyeongbok","memo":"Mặc hanbok được miễn vé vào cung; có lễ đổi gác trước cổng chính vào ban ngày.","tags":["cungđiện","hanbok"],"lat":37.579617,"lng":126.977041},{"place_id":"ChIJT8H4r9qifDURmuXJ_6m6vM0","title":"Làng Bukchon Hanok","memo":"Khu dân cư thật, có quy định giờ tham quan; đi nhẹ nói khẽ và tránh chụp vào nhà người dân.","tags":["hanok","điBộ"],"lat":37.58147,"lng":126.984952},{"place_id":"ChIJR2GkpsKifDURh6X4t1FUx1Y","title":"Insadong","memo":"Phố đồ thủ công và trà truyền thống, mua quà lưu niệm ở đây hợp lý hơn khu Myeongdong.","tags":["quàlưuniệm","tràđạo"],"lat":37.573284,"lng":126.985606}]},{"name":"Seoul ăn chơi","by":"ex2","items":[{"place_id":"ChIJqb-ne_CifDURR-yH8a3sjXM","title":"Chợ đêm Myeongdong","memo":"Đồ ăn đường phố bày bán từ chiều tối; mua mỹ phẩm thì nhớ mang hộ chiếu để được hoàn thuế.","tags":["streetfood","mỹphẩm"],"lat":37.561669,"lng":126.985844},{"place_id":"ChIJ68AiKsWYfDUROpTctLKtxtU","title":"Hongdae","memo":"Tối cuối tuần có nhiều nhóm nhảy và hát busking quanh khu phố đi bộ, không khí rất trẻ.","tags":["busking","vềđêm"],"lat":37.556197,"lng":126.925034},{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","title":"Tháp N Seoul","memo":"Lên trước hoàng hôn một chút để ngắm cả cảnh ngày lẫn đêm; đi cáp treo Namsan hoặc xe buýt đều được.","tags":["view","hoànghôn"],"lat":37.551169,"lng":126.988227}]},{"name":"Busan biển","by":"ex3","items":[{"place_id":"ChIJXwf-DlyNaDURmKxjwdWxY5k","title":"Biển Haeundae","memo":"Bãi biển nổi tiếng nhất Busan, nhiều khách sạn quanh đây nên tiện làm chỗ ở cho 2 đêm.","tags":["biển","chỗở"],"lat":35.158698,"lng":129.160384},{"place_id":"ChIJxw7HJy_taDUR-xaSTeHwbf8","title":"Biển Gwangalli","memo":"Ngắm cầu Gwangan lên đèn buổi tối; cuối tuần thường có show drone trên biển.","tags":["cầuGwangan","buổitối"],"lat":35.15317,"lng":129.118666},{"place_id":"ChIJUToRo7fpaDURo_ZMItcBfpc","title":"Làng văn hóa Gamcheon","memo":"Làng nhà nhiều màu trên sườn đồi, dốc khá nhiều nên đi taxi lên đỉnh rồi đi bộ xuống.","tags":["làngmàu","chụpảnh"],"lat":35.097394,"lng":129.010592},{"place_id":"ChIJudkrFArpaDURbbCzajeQs0c","title":"Chợ hải sản Jagalchi","memo":"Chọn hải sản ở tầng dưới rồi nhờ quán tầng trên chế biến; hỏi kỹ giá theo cân trước khi chốt.","tags":["hảisản","chợ"],"lat":35.096634,"lng":129.030797}]}],"comments":[{"place_id":"ChIJT8H4r9qifDURmuXJ_6m6vM0","by":"ex1","body":"Bukchon có giới hạn giờ tham quan đó, tụi mình đi sáng sớm luôn rồi qua Gyeongbok nhé, hai chỗ đi bộ được.","replies":[{"by":"ex2","body":"Ok, nhưng thuê hanbok ở đâu? Thuê gần cung xong mặc đi Bukchon luôn thì vừa chụp ảnh vừa được miễn vé."},{"by":"ex1","body":"Chuẩn, có cả dãy tiệm cho thuê quanh ga Anguk. Đặt trước online cho chắc."}]},{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","by":"ex2","body":"Tháp N Seoul đi buổi chiều được không? Mình muốn chụp hoàng hôn rồi xuống Myeongdong ăn tối luôn.","replies":[{"by":"ex3","body":"Hợp lý, Myeongdong ngay dưới chân Namsan. Mà cuối tháng 10 trời lạnh nhanh lắm, nhớ mang áo khoác."}]},{"place_id":"ChIJUToRo7fpaDURo_ZMItcBfpc","by":"ex3","body":"Gamcheon với Jagalchi gần nhau, gộp chung một buổi nhé: sáng Gamcheon, trưa xuống Jagalchi ăn hải sản.","replies":[{"by":"ex1","body":"Đồng ý. Ba đứa đi taxi lên Gamcheon chia ra còn rẻ hơn đi xe buýt mà đỡ leo dốc."},{"by":"ex2","body":"Hải sản để mình lo ngân sách nha, ăn chung một mâm cho tiết kiệm 😆"}]},{"place_id":"ChIJxw7HJy_taDUR-xaSTeHwbf8","by":"ex2","body":"Mình muốn xem show drone ở Gwangalli, có cần ở gần đó không?","replies":[{"by":"ex3","body":"Ở Haeundae đi tàu điện ngầm qua cũng nhanh, không cần đổi khách sạn. Nhưng nhớ xếp lịch vào tối thứ Bảy nhé."}]},{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","by":"ex1","body":"CHỐT LỊCH 📌 Ngày 1: tới Seoul, tối Hongdae. Ngày 2: Bukchon sáng sớm → Gyeongbok (hanbok) → Insadong. Ngày 3: chiều Tháp N Seoul → tối Myeongdong. Ngày 4: sáng đi KTX xuống Busan (khoảng 2,5 tiếng), chiều Haeundae, tối thứ Bảy xem drone Gwangalli. Ngày 5: Gamcheon → Jagalchi rồi ra sân bay.","replies":[{"by":"ex2","body":"Duyệt! Mình đặt vé KTX sớm luôn vì cuối tuần hay hết chỗ."},{"by":"ex3","body":"Mình lo khách sạn Haeundae 1 đêm. Lưu ý Gyeongbok nghỉ thứ Ba, ngày 2 đừng rơi vào thứ Ba nha."}]}]},{"role":"food","owner":"official","slug":"sai-gon-an-gi","kind":"collection","title":"Sài Gòn ăn gì: bánh mì, cơm tấm và phở quanh Quận 1","desc":"Những quán ăn quen thuộc quanh trung tâm Sài Gòn, từ ổ bánh mì buổi sáng đến dĩa cơm tấm sườn nướng và tô phở khuya.","themes":["SàiGòn","ănuống","bánhmì","cơmtấm","Quận1"],"sections":[{"name":"Bánh mì","by":"official","items":[{"place_id":"ChIJHcwijyEvdTERt9X0yTz8iVk","title":"Bánh mì Hòa Mã","memo":"Tiệm lâu đời nổi tiếng với bánh mì chảo ốp la, pate, xíu mại; nên đến buổi sáng vì bán chủ yếu cho bữa điểm tâm.","tags":["lâuđời","ănsáng"],"lat":10.770205,"lng":106.681594},{"place_id":"ChIJ9-1JQtgvdTER5PwDWnWbXoQ","title":"Bánh mì Mẹ Ỉn","memo":"Quán nhỏ trong hẻm gần chợ Bến Thành, bánh nướng giòn, nhân đầy đặn; hợp ghé khi đang dạo trung tâm.","tags":["trongHẻm","gầnBếnThành"],"lat":10.773823,"lng":106.697978},{"place_id":"ChIJFYPuqO8vdTERDperSLsS5P0","title":"Bánh mì A Phúc","memo":"Ngay đầu phố Tây Bùi Viện, tiện mua ăn khuya; có thể dặn ít hoặc không ớt nếu không ăn cay được.","tags":["ănkhuya","BùiViện"],"lat":10.767759,"lng":106.694613},{"place_id":"ChIJfUCdNUEvdTERPIr4YGcnPPI","title":"Bánh mì Út Thương","memo":"Nằm trong hẻm Tôn Thất Tùng, ổ bánh mì làm tại chỗ; đi bộ từ khu Phạm Ngũ Lão chỉ vài phút.","tags":["trongHẻm","nónggiòn"],"lat":10.769421,"lng":106.689851}]},{"name":"Cơm tấm","by":"official","items":[{"place_id":"ChIJR-N3eW4vdTERlrLbAwjM6tk","title":"Cơm tấm Tóp Mỡ","memo":"Dĩa cơm tấm sườn bì chả kiểu Sài Gòn, nhớ chan thêm mỡ hành và nước mắm pha; giờ trưa văn phòng thường đông.","tags":["sườnnướng","giờtrưa"],"lat":10.76826,"lng":106.698552},{"place_id":"ChIJnaR7sMQvdTER2RWEBQURVwo","title":"Cơm tấm Đề Thám","memo":"Quán bình dân ở khu phố Tây, gọi thêm trứng ốp la và canh để có một bữa no nê.","tags":["bìnhdân","phốTây"],"lat":10.768381,"lng":106.693365}]},{"name":"Phở & món Việt","by":"official","items":[{"place_id":"ChIJ_aI_CAAvdTERK01l1hAbBCM","title":"Phở Việt Nam Tôn Thất Tùng","memo":"Mở cửa suốt ngày đêm, cứu cánh cho những bữa khuya; phở miền Nam ăn kèm rau thơm, giá và tương đen.","tags":["phở","mở24h"],"lat":10.770153,"lng":106.688434},{"place_id":"ChIJu5OhvtMvdTERBiJ0Bxi-X3I","title":"MANA Station","memo":"Không gian sạch sẽ, thực đơn nhiều món Việt quen thuộc; hợp dẫn bạn bè lần đầu tới Sài Gòn thử nhiều món một lúc.","tags":["mónViệt","điNhóm"],"lat":10.776731,"lng":106.704784}]}],"comments":[]}]}$doc$::jsonb);
